def sort_array_by_moving_items_to_empty_space(nums):
    n = len(nums)

    # Check target1: [0,1,2,...,n-1]
    prefix = 0
    for i in range(n):
        if nums[i] == i:
            prefix += 1
        else:
            break
    moves1 = n - prefix

    # Check target2: [1,2，...,n-1,0]
    suffix = 0
    for i in range(n-1, -1, -1):
        expected = (i+1) % n
        if nums[i] == expected:
            suffix += 1
        else:
            break
    moves2 = n - suffix

    return min(moves1, moves2)
